form.CreateReportForm.js:
import React, { useEffect, useRef, useState } from "react";
import { getAllQuotes, getQuoteByTicketId } from "../../Services/quoteService";
import { formatDateTime, formatTime, isEmpty, stringToColor } from "../../Services/globalServiceUtils";
import {
	fetchTicketsByLoggedInUser,
	fetchTicketsByLoggedInUserV4,
	fetchTicketsService,
	getAgentsForTicketCollaborators,
} from "../../Services/ticketsService";
import FormField from "../FormField/FormField";
import {
	Alert,
	Autocomplete,
	Avatar,
	AvatarGroup,
	Box,
	Button,
	Checkbox,
	CircularProgress,
	Divider,
	FormControlLabel,
	IconButton,
	TextField,
	Tooltip,
	Typography,
	useMediaQuery,
} from "@mui/material";
import PageHeader from "../PageHeader/PageHeader";
import { useCustomTheme } from "../../Context/ThemeContext";
import { useAuth } from "../../Context/AuthContext";
import CloseIcon from "@mui/icons-material/Close";
import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import WorkLogItem from "../WorkLogItemForm/WorkLogItemForm";
import { getAllItemTypes } from "../../Services/itemsService";
import AddCircleIcon from "@mui/icons-material/AddCircle";
import { toast } from "../../Utilities/toast";
import { createBulkWorkLogs, createReport, getAllReports, getServiceReportFormOptions } from "../../Services/reportsService";
import { useNamespace } from "../../Context/NamespaceContext";
import { fetchCustomersService,fetchActiveCustomersService, fetchCustomerUsersService } from "../../Services/customerService";
import { fetchAgentsService } from "../../Services/agentService";
import { getAllBillingProfiles } from "../../Services/billingProfileService";
import { DatePicker } from "@mui/x-date-pickers";
import moment from "moment";
import { LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterMoment } from "@mui/x-date-pickers/AdapterMoment";
import { getAllAppointmentsService } from "../../Services/appointmentService";
import RowBox from "../RowBox/RowBox";
import Swal from "sweetalert2";
import _, { capitalize } from "lodash";
import { AlertService } from "../../Utilities/Template";
import { getIsTicketParticipant } from "../../Utilities/ticketAccessUtils";
import CreateAppointmentForm from "../CreateAppointmentForm/CreateAppointmentForm";

const CreateReportForm = ({
	formOpen,
	setFormOpen,
	setParentData = null,
	fetchParentData = null,
	selectedTicket = null,
	data = null,
	isEditing = false,
}) => {
	const initialFormDataRef = useRef();
	const prevAppointmentRef = useRef(null); // Add this line
	const nameEditedRef = useRef(false);
	const isLargeScreen = useMediaQuery("(min-width:1500px)");
	const { getNamespace } = useNamespace();
	const { flexRow, flexCol } = useCustomTheme();
	const { user, userMode, userDepartments, isAgent, userId, hasPermsV2 } = useAuth();
	const [customerOptions, setCustomerOptions] = useState([]);
	const [userOptions, setUserOptions] = useState([]);
	const [allCustomerUsers, setAllCustomerUsers] = useState([]);	
	const orgSetByUserRef = useRef(false)
	const [itemOptions, setItemOptions] = useState([]);
	const [allItemOptions, setAllItemOptions] = useState([]);
	const [allTickets, setAllTickets] = useState([]);
	const [appointmentOptions, setAppointmentOptions] = useState([]);
	const [allAppointmentOptions, setAllAppointmentOptions] = useState([]);
	const [allReportOptions, setAllReportOptions] = useState([]);
	const [allCustomers, setAllCustomers] = useState([]);
	const [agentOptions, setAgentOptions] = useState([]);
	const [ticketOptions, setTicketOptions] = useState([]);
	const [allAgentOptions, setAllAgentOptions] = useState([]);
	const [billingProfiles, setBillingProfiles] = useState([]);
	const [ticket, setTicket] = useState(selectedTicket ?? null);

	// Immediately apply selectedTicket to formData when provided (ticket details page shortcut)
	useEffect(() => {
		if (selectedTicket && !isEditing) {
			const tObj = typeof selectedTicket === "object" ? selectedTicket : null;
			if (tObj) setTicket(tObj);
			setFormData((prev) => ({
				...prev,
				ticket_id: tObj ? tObj.ticket_id : selectedTicket,
				org_id: tObj?.ticket_user?.org_id || prev.org_id,
				user_id: tObj?.ticket_user?.id || prev.user_id,
				name: !isEditing
					? `${getNamespace("service_report", { capitalize: true })} For ${getNamespace("ticket", {
						capitalize: true,
					})} #${tObj ? tObj.ticket_number : ""} - ${formatTime(moment())}`
					: prev.name,
			}));
		}
	}, [selectedTicket, isEditing]);
	const [possibleCollaborators, setPossibleCollaborators] = useState([]);
	const [formLoading, setFormLoading] = useState(false);
	const [formSubmitting, setFormSubmitting] = useState(false);
	const [formErrors, setFormErrors] = useState({
		ticket_id: false,
		report_id: false,
		report_form_id: false,
		workLogItems: [],
	});
	const [localSelectedIds, setLocalSelectedIds] = useState([]);
	const [submitError, setSubmitError] = useState(null);
	const [error, setError] = useState(null);
	const [formData, setFormData] = useState({
		reportDate: moment(),
		report_type: "TM",
		internal_only: false,
		name: "",
		description: "",
		org_id: "",
		user_id: "",
		staff_id: "",
		ticket_id: "",
		appointment_id: "",
	});
	const [reportFormOptions, setReportFormOptions] = useState([]);
	const [reportFormDefaultId, setReportFormDefaultId] = useState(null);
	const [selectedReportFormId, setSelectedReportFormId] = useState("");
	const [reportFormOptionsLoading, setReportFormOptionsLoading] = useState(false);
	const [allAppointmentData, setAllAppointmentData] = useState([]);
	const [createAppointmentOpen, setCreateAppointmentOpen] = useState(false);

	useEffect(() => {
		fetchData();
	}, []);

	const canCreateAppointmentFromTicket = React.useMemo(() => {
		if (!ticket) return false;
		if (!isAgent) return true; // end-users can request appointments if the UI allows it

		const staffId =
			user?.staff?.staff_id ||
			user?.staff_id ||
			user?.account?.id ||
			user?.id;

		const isTicketCollaborator =
			!!staffId &&
			(ticket?.ticket_collaborators || []).some(
				(c) => String(c?.staff_id ?? c?.collaborator_staff?.staff_id) === String(staffId)
			);

		const isAssignee =
			!!staffId &&
			String(ticket?.assigned_staff_id ?? ticket?.ticket_assignee?.staff_id ?? "") === String(staffId);

		const isAccountable =
			!!staffId &&
			String(ticket?.accountable_staff_id ?? ticket?.ticket_accountable?.staff_id ?? "") === String(staffId);

		const isOwner =
			!!staffId &&
			String(ticket?.created_by_staff_id ?? ticket?.ticket_creator_staff?.staff_id ?? "") === String(staffId);

		const isTicketParticipant = getIsTicketParticipant({
			isAgent,
			isTicketCollaborator,
			isAssignee,
			isAccountable,
			isOwner,
			ticketDeptId: ticket?.dept_id ?? ticket?.department_id ?? null,
			userDepartments,
		});

		// Dept-scoped permission; allow participants to create when they have appointment.create in ANY dept.
		return (
			hasPermsV2("appointment_management.appointment.create", ticket?.dept_id) ||
			(isTicketParticipant && hasPermsV2("appointment_management.appointment.create"))
		);
	}, [ticket, isAgent, user, userDepartments, hasPermsV2]);

	const buildPrefilledAppointmentData = React.useCallback(() => {
		if (!ticket) return null;
		const ticketCustomerId = ticket?.ticket_user?.org_id || ticket?.ticket_user?.organization?.id || ticket?.org_id || null;
		const ticketUserId = ticket?.user_id || ticket?.ticket_user?.id || null;
		const ticketSiteId = ticket?.site_id || ticket?.location_id || ticket?.site?.site_id || null;
		const staffAssigned =
			ticket?.assigned_staff_id ?? ticket?.ticket_assignee?.staff_id ?? user?.staff?.staff_id ?? null;

		return {
			ticket: ticket.ticket_id,
			customer_id: ticketCustomerId,
			user_id: ticketUserId,
			location_id: ticketSiteId,
			staff_assigned: staffAssigned,
		};
	}, [ticket, user]);

	const handleAppointmentCreatedFromReport = async (appt) => {
		setCreateAppointmentOpen(false);
		try {
			await fetchAppointments();
		} catch (_err) {
			// ignore: fallback to setting appointment_id anyway
		}
		if (appt?.id != null) {
			setFormData((prev) => ({ ...prev, appointment_id: appt.id }));
		}
	};

	// useEffect(() => {
	// 	if (!isEmpty(formData.ticket_id)) {
	// 		fetchQuote(formData.ticket_id);
	// 	}
	// }, [formData.ticket_id]);

	useEffect(() => {
		if (ticketOptions.length > 0 && ticket) {
			setFormData((prev) => ({ ...prev, ticket_id: ticket.ticket_id }));
		}
	}, [ticketOptions]);

	useEffect(() => {
		if (possibleCollaborators.length > 0 && userId) {
			setLocalSelectedIds((prev) => [...prev, userId]);
		}
	}, [possibleCollaborators, userId]);

	// Load eligible Service Report checklists based on ticket service type + report flow
	useEffect(() => {
		let cancelled = false;

		const load = async () => {
			if (!formOpen) return;
			if (!formData.ticket_id) {
				setReportFormOptions([]);
				setReportFormDefaultId(null);
				setSelectedReportFormId("");
				return;
			}

			try {
				setReportFormOptionsLoading(true);
				const flow = formData.internal_only ? "internal_only" : "customer_visibility";
				const resp = await getServiceReportFormOptions({ ticket_id: formData.ticket_id, report_flow: flow });
				if (cancelled) return;

				if (resp?.status) {
					const forms = Array.isArray(resp?.data?.forms) ? resp.data.forms : [];
					const defId = resp?.data?.default_form_id ? String(resp.data.default_form_id) : null;
					setReportFormOptions(forms);
					setReportFormDefaultId(defId);

					if (forms.length === 1) {
						setSelectedReportFormId(String(forms[0].id));
					} else if (defId) {
						setSelectedReportFormId(String(defId));
					} else {
						setSelectedReportFormId("");
					}
				} else {
					setReportFormOptions([]);
					setReportFormDefaultId(null);
					setSelectedReportFormId("");
				}
			} catch (e) {
				if (cancelled) return;
				setReportFormOptions([]);
				setReportFormDefaultId(null);
				setSelectedReportFormId("");
			} finally {
				if (!cancelled) setReportFormOptionsLoading(false);
			}
		};

		load();
		return () => {
			cancelled = true;
		};
	}, [formOpen, formData.ticket_id, formData.internal_only]);

	useEffect(() => {
		if (ticketOptions.length > 0 && ticket) {
			setFormData((prev) => ({
				...prev,
				ticket_id: !isEditing ? ticket?.ticket_id || null : data?.ticket_id,
				org_id: !isEditing ? ticket?.ticket_user?.org_id : data?.ticket?.ticket_user?.org_id,
				user_id: !isEditing ? ticket?.ticket_user?.id : data?.ticket?.user_id,
				// Auto-generate name for new reports when ticket changes unless the user has manually edited the name
				name: !isEditing
					? !nameEditedRef.current
						? `${getNamespace("service_report", { capitalize: true })} For ${getNamespace("ticket", {
							capitalize: true,
						})} #${ticket.ticket_number} - ${formatTime(moment())}`
						: prev.name
					: data?.report_name,
			}));
		}

		if (ticketOptions.length > 0 && ticket) {
			const reportedAppointmentIds = new Set(
				(allReportOptions || [])
					.filter((r) => r.ticket_id === ticket.ticket_id && r.appointment_id != null)
					.map((r) => r.appointment_id)
			);

			// keep appointments for this ticket that are NOT present in reportedAppointmentIds
			const filtered = (allAppointmentOptions || []).filter(
				(a) => a.ticket_id === ticket.ticket_id && !reportedAppointmentIds.has(a.value)
			);

			const createOpt = canCreateAppointmentFromTicket
				? [{
						label: `Create New ${getNamespace("appointment", { capitalize: true, plural: false })}`,
						value: "__create__",
				  }]
				: [];

			setAppointmentOptions([...filtered, ...createOpt]);
		}
	}, [ticketOptions, ticket, allAppointmentOptions, allReportOptions, canCreateAppointmentFromTicket, getNamespace]);

	useEffect(() => {
		if (isEditing) return;

		if (!formData.ticket_id || formData.ticket_id === "" || isEmpty(formData.ticket_id)) {
			// Ticket cleared — reset ticket state and unlock customer/user fields
			setTicket(null);
			setAppointmentOptions([]);
			setFormData((prev) => ({
			...prev,
			org_id: "",
			user_id: "",
			appointment_id: "",   // also clear appointment since it's ticket-scoped
			}));
			return;
		}

		// Ticket selected — find and set it
		const selTicket = allTickets.find((t) => t.ticket_id === formData.ticket_id);
		if (selTicket) setTicket(selTicket);
	}, [formData.ticket_id, allTickets, isEditing]);

	useEffect(() => {
		if (!formData.user_id || formData.user_id === "") return;
		if (formData.org_id && formData.org_id !== "") return; // already set
		if (ticket) return; // ticket controls org/user, don't interfere

		const selectedUser = allCustomerUsers.find((u) => u.value === formData.user_id);
		if (selectedUser?.org_id) {
			orgSetByUserRef.current = true; // signal: don't clear user
			setFormData((prev) => ({ ...prev, org_id: selectedUser.org_id }));
		}
	}, [formData.user_id, allCustomerUsers, ticket]);

	useEffect(() => {
		if (ticket) return; // ticket controls these fields, skip

		const baseOptions = allCustomerUsers || [];

		if (formData.org_id && formData.org_id !== "") {
			const filteredUsers = baseOptions.filter((u) => u.org_id === formData.org_id);
			setUserOptions(filteredUsers);

			if (orgSetByUserRef.current) {
			// org was set by user selection — keep the user
			orgSetByUserRef.current = false;
			} else {
			// org was changed manually — clear user if it belongs to a different org
			if (formData.user_id) {
				const selectedUser = baseOptions.find((u) => u.value === formData.user_id);
				if (selectedUser?.org_id !== formData.org_id) {
				setFormData((prev) => ({ ...prev, user_id: "" }));
				}
			}
			}
		} else {
			// No org selected — restore full user list
			setUserOptions(baseOptions);
		}
	}, [formData.org_id, allCustomerUsers, ticket]);

	useEffect(() => {
	if (allTickets.length === 0) return;

	let filtered = allTickets;

	if (formData.org_id && formData.org_id !== "") {
		filtered = filtered.filter(
		(t) => t.ticket_user?.org_id === formData.org_id
		);
	}

	if (formData.user_id && formData.user_id !== "") {
		filtered = filtered.filter(
		(t) =>
			t.ticket_user?.id === formData.user_id ||
			t.user_id === formData.user_id
		);
	}

	const ticketOpts = filtered.map((t) => ({
		value: t.ticket_id,
		label: `${t.ticket_number} - ${t.ticket_subject}`,
	}));
	setTicketOptions(ticketOpts);

	// Auto-select if exactly 1 ticket matches
	if (filtered.length === 1 && !formData.ticket_id) {
		setFormData((prev) => ({ ...prev, ticket_id: filtered[0].ticket_id }));
	}

	// Clear stale ticket_id if it's no longer in filtered list
	if (
		formData.ticket_id &&
		!filtered.some((t) => t.ticket_id === formData.ticket_id)
	) {
		setFormData((prev) => ({ ...prev, ticket_id: "" }));
	}
	}, [formData.org_id, formData.user_id, allTickets]);

	useEffect(() => {
		if (
			ticketOptions.length > 0 &&
			customerOptions.length > 0 &&
			userOptions.length > 0 &&
			possibleCollaborators.length > 0
		) {
			setFormLoading(false);
		}
	}, [ticketOptions, allItemOptions, customerOptions, userOptions, appointmentOptions, possibleCollaborators]);

	// Auto-sync appointment assigned staff with report assignees
	useEffect(() => {
		if (allAppointmentData.length === 0) return;

		const selectedAppointment = allAppointmentData.find(appt => appt.id === formData.appointment_id);

		// Remove previous appointment's staff if appointment changed
		if (prevAppointmentRef.current && prevAppointmentRef.current.id !== formData.appointment_id) {
			const prevStaffIds = prevAppointmentRef.current.assigned_staff?.map(staff => staff.staff_id) || [];
			setLocalSelectedIds(prev => prev.filter(id => !prevStaffIds.includes(id)));
		}

		// Add new appointment's staff
		if (selectedAppointment && selectedAppointment.assigned_staff) {
			const appointmentStaffIds = selectedAppointment.assigned_staff.map(staff => staff.staff_id);

			setLocalSelectedIds(prev => {
				const newIds = [...prev];
				appointmentStaffIds.forEach(staffId => {
					if (!newIds.includes(staffId)) {
						newIds.push(staffId);
					}
				});
				return newIds;
			});

			prevAppointmentRef.current = selectedAppointment;
		} else if (!formData.appointment_id) {
			// Clear the ref when no appointment is selected
			prevAppointmentRef.current = null;
		}
	}, [formData.appointment_id, allAppointmentData]);

	const fetchData = async () => {
		try {
			setFormLoading(true);
			await Promise.all([
				fetchItemTypes(),
				fetchBillingProfiles(),
				fetchTickets(),
				fetchCustomers(),
				fetchCustomerUsers(),
				fetchAppointments(),
				fetchReports(),
				fetchCollaboratorAgentsOptions(),
			]);
		} finally {
			setFormLoading(false);
		}
	};

	const fetchReports = async () => {
		const response = await getAllReports();
		if (response.status) {
			setAllReportOptions(response.data);
		} else {
			setAllReportOptions(null);
		}
	};

	const fetchItemTypes = async () => {
		const response = await getAllItemTypes();
		if (response.status) {
			setAllItemOptions(response.data);
		} else {
			setAllItemOptions(null);
		}
	};

	const fetchBillingProfiles = async () => {
		try {
			const response = await getAllBillingProfiles();
			console.log(response);
			if (response?.status) {
				setBillingProfiles(response.data || []);
			} else {
				setBillingProfiles([]);
			}
		} catch (error) {
			console.log(error);
			setBillingProfiles([]);
		}
	};

	const fetchTickets = async () => {
		try {
			const req_body = {
				exclude_closed_status: true,
				permission_required: "service_report_management.service_report.create",
			};
			const response = await fetchTicketsByLoggedInUserV4(req_body);
			if (response.status) {
				setError(null);
				const rawTickets = response.data || [];

				// Ensure user is authorized as an agent
				let filteredTickets = userMode === "agent" ? rawTickets : [];

				console.log("Filtered Tickets (Backend)", filteredTickets);
				setAllTickets(filteredTickets);
				const ticketUserCounts = filteredTickets.map((ticket) => ({
					value: ticket.ticket_id,
					label: `${ticket.ticket_number} - ${ticket.ticket_subject}`,
				}));
				console.log("Tickets", ticketUserCounts);
				setTicketOptions(ticketUserCounts);
			} else {
				setError("Failed Fetching tickets");
				setTicketOptions([]);
			}
		} catch (error) {
			setError("Failed Fetching tickets catch");
			setTicketOptions([]);
		}
	};

	const fetchCustomers = async () => {
		try {
			const response = await fetchActiveCustomersService();
			if (response.status) {
				console.log(response);
				setAllCustomers(response.data);
				setError(null);
				const customerUserCounts = response.data.map((customer) => ({
					value: customer.id,
					label: customer.name,
				}));
				console.log(customerUserCounts);
				setCustomerOptions(customerUserCounts);
			} else {
				setError("Failed Fetching Customers");
				setCustomerOptions([]);
			}
		} catch (error) {
			setError("Failed Fetching Customers");

			setCustomerOptions([]);
		}
	};

	const fetchCustomerUsers = async () => {
		try {
			const response = await fetchCustomerUsersService();
			if (response.status) {
				const customerUserCounts = response.data.map((user) => ({
					org_id: user.org_id,
					customer: user.organization.name,
					email: user.emails[0].address,
					value: user.id,
					label: user.name,
				}));
				// Sort by customer name to prevent duplicate group headers
				const sortedUserOptions = customerUserCounts.sort((a, b) => {
					// First sort by customer name
					if (a.customer !== b.customer) {
						return a.customer.localeCompare(b.customer);
					}
					// Then sort by user name within the same customer
					return a.label.localeCompare(b.label);
				});
				setAllCustomerUsers(sortedUserOptions);
				setUserOptions(sortedUserOptions);
			} else {
				setError("Failed Fetching Customer Users");
				setUserOptions([]);
			}
		} catch (error) {
			setError("Failed Fetching Customer Users");
			setUserOptions([]);
		}
	};

	const fetchAppointments = async () => {
		try {
			const response = await getAllAppointmentsService();
			if (response.status) {
				const filtered = (response.data || []).filter((appt) => {
					const state = String(appt?.appointment_status?.state || "").toLowerCase();
					return state === "scheduled" && !appt?.service_report;
				});
				console.log("Filtered Appointments:", filtered);

				// Store full appointment data
				setAllAppointmentData(filtered);

				const appointmentOpt = filtered.map((appt) => ({
					label: `${appt?.title}: ${formatDateTime(appt?.start_datetime)} - ${formatDateTime(
						appt?.end_datetime
					)}`,
					value: appt?.id,
					ticket_id: appt?.ticket_id,
					assigned_staff: appt?.assigned_staff || [], // Include assigned staff
				}));
				setAllAppointmentOptions(appointmentOpt);
				setAppointmentOptions(appointmentOpt);
			} else {
				setError("Failed Fetching Customer Users");
				setAllAppointmentData([]);
				setAllAppointmentOptions([]);
				setAppointmentOptions([]);
			}
		} catch (error) {
			setError("Failed Fetching Customer Users");
			setAllAppointmentData([]);
			setAllAppointmentOptions([]);
			setAppointmentOptions([]);
		}
	};

	const processUsers = (users, userDepartments) => {
		return isAgent
			? users
					.map((user) => {
						const sortedDepts = [...user.staff_departments].sort((a, b) => b.is_primary - a.is_primary);
						const deptsStr = sortedDepts
							.map((d) => `${d.department?.name}${d.is_primary ? " (Primary)" : ""}`)
							.join(", ");

						return {
							id: user.staff_id,
							name: user.name,
							depts: deptsStr,
							dept_ids: user.staff_departments.map((d) => d.dept_id), // keep for sorting
						};
					})
					.sort((a, b) => {
						const aHasAccess = a.dept_ids.some((id) => userDepartments.includes(id));
						const bHasAccess = b.dept_ids.some((id) => userDepartments.includes(id));

						if (aHasAccess && !bHasAccess) return -1;
						if (!aHasAccess && bHasAccess) return 1;
						return a.name.localeCompare(b.name);
					})
			: users.map((user) => {
					const sortedDepts = [...user.staff_departments].sort((a, b) => b.is_primary - a.is_primary);
					const deptsStr = sortedDepts
						.map((d) => `${d.department?.name}${d.is_primary ? " (Primary)" : ""}`)
						.join(", ");

					return {
						id: user.staff_id,
						name: user.name,
						depts: deptsStr,
						dept_ids: user.staff_departments.map((d) => d.dept_id), // keep for sorting
					};
			  });
	};

	const fetchCollaboratorAgentsOptions = async () => {
		try {
			const response = await fetchAgentsService();
			if (response.status) {
				// Step 1: Process raw data into the format needed for the component
				const allUsers = processUsers(response.data, userDepartments);

				// Step 2: Second pass - Identify duplicates and update labels
				const handledDuplicates = allUsers.map((agent) => {
					// Count agents with the same name (case-insensitive)
					const sameNameCount = allUsers.filter(a => 
						(a.name || '').toLowerCase().trim() === (agent.name || '').toLowerCase().trim()
					);

					// If duplicates exist, modify the 'name' property (which is used for labels)
					if (sameNameCount.length > 1) {
						// Find original agent data to get email/username
						const originalAgent = response.data.find(a => a.staff_id === agent.id);
						const extraInfo = originalAgent?.staff_account?.email || 
										originalAgent?.staff_account?.username || 
										`ID: ${agent.id}`;

						return {
							...agent,
							name: `${agent.name} (${extraInfo})`, // This updates the display in the dropdown
						};
					}
					return agent;
				});

				setPossibleCollaborators(handledDuplicates);
			} else {
				setError("Failed to Fetch Staff Details.");
			}
		} catch (error) {
			console.error(error);
			setError("Failed to Fetch Staff Details.");
		}
	};

	const onCheckboxChange = (optionId, checked) => {
		setLocalSelectedIds((prev) => {
			if (checked) return [...prev, optionId];
			return prev.filter((id) => id !== optionId);
		});
	};

	const stringAvatar = (name) => {
		const trimmedName = name?.trim() || "";
		const parts = trimmedName.split(" ");
		const initials = `${parts[0]?.[0] ?? ""}${parts[1]?.[0] ?? ""}`;
		return {
			sx: {
				bgcolor: stringToColor(trimmedName),
				width: 25,
				height: 25,
				fontSize: "12px",
			},
			children: initials.toUpperCase(),
		};
	};

	const handleClose = () => {
		const hasChanged = !_.isEqual(formData, initialFormDataRef.current);

		if (!hasChanged) {
			setFormOpen(false);
			setFormData({
				reportDate: moment(),
				report_type: "TM",
				name: "",
				description: "",
				org_id: "",
				user_id: "",
				staff_id: "",
				ticket_id: "",
				appointment_id: "",
			});
			return;
		}
		AlertService.confirmDiscard().then((result) => {
			if (result.isConfirmed) {
				setFormOpen(false);
				setFormData({
					reportDate: moment(),
					report_type: "TM",
					name: "",
					description: "",
					org_id: "",
					user_id: "",
					staff_id: "",
					ticket_id: "",
					appointment_id: "",
				});
			}
		});
	};

	const handleDateChange = (name) => (newValue) => {
		handleFormChange({ target: { name, value: moment(newValue) } });
	};

	const handleFormChange = (e) => {
		const { name, value, type, checked } = e.target;
		const normalizedValue = type === "checkbox" ? checked : (value && typeof value === "object" && value.value !== undefined ? value.value : value);

		// Appointment dropdown: allow "Create New Appointment" option inside the list
		if (name === "appointment_id" && normalizedValue === "__create__") {
			setCreateAppointmentOpen(true);
			return;
		}

		// If the user edits the report name field, mark it so we don't overwrite it on ticket change
		if (name === "name") {
			nameEditedRef.current = true;
		}

		setFormData((prev) => ({
			...prev,
			[name]: normalizedValue,
		}));

		if (formErrors[name]) {
			setFormErrors((prev) => ({ ...prev, [name]: false }));
		}
	};

	const handleSubmit = async (isDraft) => {
		const entity = "Service Report";
		const action = "create";
		const trimmedName = formData.name?.trim();

		// --- 0. Permission Check ---
		// Get the department ID from the selected ticket
		const selectedTicket = allTickets.find(t => t.ticket_id === formData.ticket_id);
		const ticketDeptId = selectedTicket?.dept_id;

		const staffId =
			user?.staff?.staff_id ||
			user?.staff_id ||
			user?.account?.id ||
			user?.id;
		const isTicketParticipant = getIsTicketParticipant({
			isAgent,
			isTicketCollaborator:
				!!staffId &&
				(selectedTicket?.ticket_collaborators || []).some(
					(c) => String(c?.staff_id ?? c?.collaborator_staff?.staff_id) === String(staffId)
				),
			isAssignee:
				!!staffId &&
				String(selectedTicket?.assigned_staff_id ?? selectedTicket?.ticket_assignee?.staff_id ?? "") === String(staffId),
			isAccountable:
				!!staffId &&
				String(selectedTicket?.accountable_staff_id ?? selectedTicket?.ticket_accountable?.staff_id ?? "") === String(staffId),
			isOwner:
				!!staffId &&
				String(selectedTicket?.created_by_staff_id ?? selectedTicket?.ticket_creator_staff?.staff_id ?? "") === String(staffId),
			ticketDeptId: ticketDeptId ?? null,
			userDepartments,
		});

		const canCreateReport =
			hasPermsV2("service_report_management.service_report.create", ticketDeptId) ||
			(isTicketParticipant && hasPermsV2("service_report_management.service_report.create"));

		if (!canCreateReport) {
			AlertService.logicFailure(
				action,
				entity,
				`You do not have permission to create a ${getNamespace("service_report", { capitalize: false, plural: false })} for this ${getNamespace("ticket", { capitalize: false, plural: false })}'s department.`
			);
			setSubmitError(`You do not have permission to create a ${getNamespace("service_report", { capitalize: false, plural: false })} for this ${getNamespace("ticket", { capitalize: false, plural: false })}'s department.`);
			return;
		}

		// --- 1. Validation Logic ---
		const errors = {};
		if (!trimmedName) errors.name = true;
		if (!formData.report_type) errors.report_type = true;
		if (!formData.ticket_id) errors.ticket_id = true;
		if (Object.keys(errors).length > 0) {
			setFormErrors(errors);
			// Validation Failure 1 (Required Fields)
			AlertService.logicFailure(
				action,
				entity,
				"Please fill all required fields."
			);
			setSubmitError("Please fill all required fields.");
			return;
		}
		if(trimmedName.length > 256) {
			setFormErrors({ name: true });
			// Validation Failure 2 (Length Constraint)
			AlertService.logicFailure(
				action,
				entity,
				`${getNamespace("service_report",{capitalize: true})} name cannot exceed 256 characters.`
			);
			setSubmitError(`${getNamespace("service_report",{capitalize: true})} name cannot exceed 256 characters.`);
			return;
		}
		setSubmitError("");
		setFormErrors({});

		setFormSubmitting(true);

		const staff_ids = Array.from(new Set(localSelectedIds));
		console.log("Submitting with assignees:", formData);
		let req_body = {
			ticket_id: formData?.ticket_id || null,
			report_name: trimmedName,
			staff_ids,
			type: formData.report_type,
			report_flow: formData?.internal_only ? "internal_only" : "customer_visibility",
			appointment_id: formData?.appointment_id || null,
			notes: formData?.description || "",
		};
		// If checklists exist, always send an explicit selection: 0 => "no checklist"
		if (reportFormOptions.length > 0) {
			req_body.report_form_id = selectedReportFormId ? Number(selectedReportFormId) : 0;
		}

		try {
		const reportResponse = await createReport(req_body);
		if (reportResponse.status) {
			const report = reportResponse.data;
			const newData = {
				id: report.report_id,
				name: report?.report_name || "-",
				report_number: report.report_number,
				quote_number: report?.quote?.quote_number || null,
				report_creator: report?.report_creator?.name || "",
				created: report.createdAt,
				report_status: report?.report_status,
				report: report,
			};

			if (setParentData) {
				setParentData((prev) => (Array.isArray(newData) ? [...prev, ...newData] : [...prev, newData]));
			}
			// Notify app to refresh ticket/service report aggregates
			window.dispatchEvent(new CustomEvent("service_reports:updated"));

				// Success Alert (USING ALERT SERVICE - createSuccess Toast)
				AlertService.createSuccess(
					entity,
					reportResponse.message || `${entity} created successfully.`
				);

				// Reset form state
 			setFormOpen(false);
 			setFormData({
 				reportDate: moment(),
 				report_type: "TM",
 				internal_only: false,
 				name: "",
 				description: "",
 				org_id: "",
 				user_id: "",
 				staff_id: "",
 				ticket_id: "",
 				appointment_id: "",
 			});
			setReportFormOptions([]);
			setReportFormDefaultId(null);
			setSelectedReportFormId("");

 		} else {
				// API Failure (Logic Failure Toast)
				AlertService.logicFailure(
					action,
					entity,
					reportResponse.message || "Failed to create report. Please check the data."
				);
			setError(reportResponse.message);
			}
		} catch (error) {
			// System/Network Error (System Error Toast)
			AlertService.systemError(
				error.message || `Failed to ${action} ${entity}. Network error.`
			);
			setError(error.message);
		} finally {
			setFormSubmitting(false);
		}
	};

	const localSelectedObjects = possibleCollaborators.filter((o) => localSelectedIds.includes(o.id));

	if (formSubmitting || formLoading) {
		return (
			<Box
				p={2}
				width="50vw"
				sx={{ ...flexCol, justifyContent: "center", alignItems: "center", minHeight: "100vh" }}>
				<CircularProgress />
				{formSubmitting && (
					<Typography variant="h6" mt={2}>
						Creating{" "}
						{getNamespace("service_report", {
							capitalize: true,
							plural: false,
						})}
					</Typography>
				)}
			</Box>
		);
	}

	return (
		<>
			<LocalizationProvider dateAdapter={AdapterMoment}>
				<Box
					p={2}
					width="50vw"
					sx={{ display: "flex", flexDirection: "column", height: "100%" }}>
					<Box
						sx={{
							...flexRow,
							justifyContent: "space-between",
							width: "100%",
						}}>
						<PageHeader
							title={`Create New ${getNamespace("service_report", {
								capitalize: true,
								plural: false,
							})}`}
							subtitle={`Fill out the form below to create a ${getNamespace("service_report", {
								capitalize: true,
								plural: false,
							})} for the ${getNamespace("ticket", {
								capitalize: true,
								plural: false,
							})}`}
						/>
						<Tooltip title="Close the Form">
							<IconButton size="small" onClick={handleClose}>
								<CloseIcon />
							</IconButton>
						</Tooltip>
					</Box>
					{submitError && (
						<Alert severity="error" sx={{ mb: 2 }}>
							{submitError}
						</Alert>
					)}
					<Box
						sx={{
							flexGrow: 1,
							display: "flex",
							flexDirection: "column",
							gap: 2,
							overflowY: "auto",
							px: 2,
							py: 1,
						}}>
 						<FormField
 							type="select"
 							label={`${getNamespace("service_report", {
 								capitalize: true,
 								plural: false,
 							})} Type`}
							name="report_type"
							value={formData.report_type}
							error={formErrors.report_type}
							onChange={handleFormChange}
							options={[
								{
									label: `Fixed Fee & Materials ${getNamespace("service_report", {
										capitalize: true,
									})}`,
									value: "FFM",
								},
								{
									label: `Time & Material ${getNamespace("service_report", { capitalize: true })}`,
									value: "TM",
								},
							]}
							showRequired={true}
						/>
						{isAgent && (
							<FormControlLabel
								sx={{ width: "fit-content", userSelect: "none" }}
								control={
									<Checkbox
										name="internal_only"
										checked={Boolean(formData.internal_only)}
										onChange={handleFormChange}
									/>
								}
								label={
									<Box display="flex" alignItems="center" columnGap={0.75}>
										<Typography variant="body2">
											{`Internal Only`}
										</Typography>
										<Tooltip
											arrow
											placement="right"
											title={`When enabled, this ${getNamespace("service_report", {
												capitalize: true,
												plural: false,
											})} will be visible only to internal ${getNamespace("agent", {
												capitalize: true,
												plural: false,
											})} and hidden from ${getNamespace(
												"organization_user",
												{ capitalize: true }
											)}.`}>
											<Box
												sx={{
													display: "flex",
													alignItems: "center",
													color: "text.secondary",
												}}>
												<InfoOutlinedIcon fontSize="small" />
											</Box>
										</Tooltip>
									</Box>
								}
							/>
						)}
						{reportFormOptionsLoading ? (
							<Box display="flex" alignItems="center" columnGap={1}>
								<CircularProgress size={16} />
								<Typography variant="body2">
									Loading {getNamespace("custom_form", { capitalize: false, plural: false })} options...
								</Typography>
							</Box>
						) : reportFormOptions.length > 0 ? (
							<FormField
								type="select"
								label={`${getNamespace("custom_form", { capitalize: true, plural: false })}`}
								name="report_form_id"
								value={selectedReportFormId}
								error={formErrors.report_form_id}
								onChange={(e) => {
									setSelectedReportFormId(e.target.value);
									if (formErrors.report_form_id) {
										setFormErrors((prev) => ({ ...prev, report_form_id: false }));
									}
								}}
								options={[
									{ label: "-- None --", value: "" },
									...reportFormOptions.map((f) => ({
										label: f?.name || f?.title || `Form #${f?.id}`,
										value: String(f?.id),
									})),
								]}
								showRequired={false}
							/>
						) : null}
						<FormField
							type={"text"}
							label={`${getNamespace("service_report", {
								capitalize: true,
								plural: false,
							})} Name`}
							name={"name"}
							showRequired={true}
							placeholder={`Please enter name for the ${getNamespace("service_report", {
								capitalize: true,
								plural: false,
							})}`}
							value={formData.name}
							error={formErrors.name}
							onChange={handleFormChange}
						/>
						<Box display="flex" alignItems="center">
							<Box width="200px" minWidth="200px">
								<Typography variant="body1" fontWeight={"bold"}>
									{getNamespace("service_report", {
										capitalize: true,
										plural: false,
									})}{" "}
									Date <span style={{ color: "red" }}>*</span>
								</Typography>
							</Box>
							<DatePicker
								value={formData.reportDate}
								onChange={handleDateChange("reportDate")}
								slotProps={{
									textField: {
										size: "small",
										error: formErrors?.reportDate,
									},
								}}
								sx={{ flex: 1, minWidth: 130, width: "100%" }}
							/>
						</Box>

						<Divider flexItem sx={{ my: "10px" }} />
						<FormField
							type="autocomplete"
							label={`${getNamespace("ticket", {
								capitalize: true,
								plural: false,
							})}`}
							name="ticket_id"
							value={formData.ticket_id}
							error={formErrors.ticket_id}
							onChange={handleFormChange}
							options={ticketOptions}
							showRequired={true}
							disabled={false}
						/>
						<FormField
							type="autocomplete"
							label={getNamespace("organization", { capitalize: true, plural: false })}
							name="org_id"
							value={formData.org_id}
							error={formErrors.org_id}
							onChange={handleFormChange}
							options={customerOptions}
							showRequired={true}
							disabled={ticket ? true : false}
						/>
						<FormField
							type="groupedByCustomer-UserDropdown"
							label={getNamespace("organization_user", { capitalize: true, plural: false })}
							name="user_id"
							value={formData.user_id}
							error={formErrors.user_id}
							onChange={handleFormChange}
							options={userOptions}
							showRequired={true}
							disabled={ticket ? true : false}
						/>
						<Divider flexItem sx={{ my: "10px" }} />

						<Box display="flex" alignItems="center">
							<Box width="200px" minWidth="200px">
								<Typography variant="body1" fontWeight={"bold"}>
									Assignee(s)
								</Typography>
							</Box>

							<Autocomplete
								multiple
								size="small"
								fullWidth
								options={possibleCollaborators}
								value={localSelectedObjects}
								disableCloseOnSelect
								getOptionLabel={(option) => option?.name || "-- Unassigned --"}
								isOptionEqualToValue={(option, value) => option.id === value.id}
								renderTags={(tagValue) => (
									<AvatarGroup
										max={5}
										sx={{
											"& .MuiAvatar-root": { width: 25, height: 25, fontSize: "12px" },
											flexWrap: "nowrap",
										}}>
										{tagValue.map((option) => (
											<Tooltip key={`${option.id}_${option.dept_id}`} title={option.name}>
												<Avatar {...stringAvatar(option.name)} />
											</Tooltip>
										))}
									</AvatarGroup>
								)}
								renderInput={(params) => <TextField {...params} placeholder={"Select Assignee(s)"} />}
								renderOption={(props, option, { selected }) => (
									<Box
										key={`${option.id}_avatarGroup`}
										component="li"
										sx={{ width: "100%", px: 0.75 }}
										{...props}
										onClick={(e) => {
											e.preventDefault(); // prevent autocomplete default behavior
											onCheckboxChange(option.id, !localSelectedIds.includes(option.id));
										}}>
										<Box display="flex" columnGap={0.5} alignItems="center">
											<Checkbox
												checked={localSelectedIds.includes(option.id)}
												onChange={(e) => onCheckboxChange(option.id, e.target.checked)}
												onClick={(e) => e.stopPropagation()} // prevent closing
											/>
											<RowBox sx={{ columnGap: 1, alignItems: "center", width: "100%" }}>
												<Avatar {...stringAvatar(option.name || "John Doe")} />
												<Tooltip
													title={`${option.name} Access: ${option.depts}`}
													arrow
													placement="right">
													<Box>
														<Typography variant="body1" sx={{ fontWeight: 500 }}>
															{option.name}
														</Typography>

														<Typography
															variant="body2"
															color="text.secondary"
															fontSize="11px"
															fontStyle="italic"
															sx={{
																whiteSpace: "nowrap",
																overflow: "hidden",
																textOverflow: "ellipsis",
																maxWidth: "120px", // ensures ellipsis works
																display: "block",
															}}>
															{option.depts}
														</Typography>
													</Box>
												</Tooltip>
											</RowBox>
										</Box>
									</Box>
								)}
								sx={{
									width: "100%",
									"& .MuiAutocomplete-inputRoot": {
										flexWrap: "nowrap", // prevent chips/input from wrapping
									},
									"& .MuiAutocomplete-inputRoot .MuiAutocomplete-input": {
										whiteSpace: "nowrap",
									},
								}}
							/>
						</Box>
						<Divider flexItem sx={{ my: "10px" }} />
						<Box sx={{ width: "100%" }}>
							<FormField
								type="autocomplete"
								label={`${getNamespace("appointment", {
									capitalize: true,
									plural: false,
								})}`}
								name="appointment_id"
								value={formData.appointment_id}
								error={formErrors.appointment_id}
								onChange={handleFormChange}
								options={appointmentOptions}
								showRequired={false}
								disabled={appointmentOptions.length <= 0 ? true : false}
							/>
							{formData.ticket_id &&
								appointmentOptions.filter((o) => o?.value !== "__create__").length <= 0 && (
								<Box sx={{ mt: 1, display: "flex", alignItems: "center", gap: 1, flexWrap: "wrap" }}>
									<Typography variant="body2" color="text.secondary" fontSize="11px">
										No available {getNamespace("appointment", { capitalize: false, plural: true })} for this {getNamespace("ticket", { capitalize: false, plural: false })}.
									</Typography>
									{/* {canCreateAppointmentFromTicket && (
										<Button
											size="small"
											variant="outlined"
											startIcon={<AddCircleIcon />}
											onClick={() => setCreateAppointmentOpen(true)}>
											Create New {getNamespace("appointment", { capitalize: true, plural: false })}
										</Button>
									)} */}
								</Box>
							)}
						</Box>
						<FormField
							type={"textarea"}
							label={"Description"}
							name={"description"}
							placeholder="Please enter description..."
							value={formData.description}
							error={formErrors.description}
							onChange={handleFormChange}
						/>

						<Typography variant="body1" color="text.secondary" fontSize={"11px"}>
							<b>Note: </b> Work Logs will be added later on after the{" "}
							{getNamespace("service_report", {
								capitalize: true,
								plural: false,
							})}{" "}
							is created
						</Typography>
					</Box>
					<Box display="flex" justifyContent="space-between" mt={3} columnGap={1}>
						<Button size="small" variant="outlined" onClick={handleClose}>
							Cancel
						</Button>
						<Box display={"flex"} columnGap={1}>
							<Button
								size="small"
								variant="contained"
								color="primary"
								onClick={() => handleSubmit(false)}>
								Save
							</Button>
						</Box>
					</Box>
				</Box>
			</LocalizationProvider>

			<CreateAppointmentForm
				formOpen={createAppointmentOpen}
				setFormOpen={setCreateAppointmentOpen}
				isPrefilled={true}
				appointmentData={buildPrefilledAppointmentData()}
				prefilledTitle={
					ticket?.ticket_number
						? `${getNamespace("appointment", { capitalize: true, plural: false })} for ${getNamespace("ticket", {
								capitalize: true,
								plural: false,
						  })} #${ticket.ticket_number}`
						: ""
				}
				ticketAccessOverride={true}
				lockPrefilledTicket={true}
				hideServiceReportField={true}
				suppressAppointmentsUpdatedEvent={true}
				onSuccess={handleAppointmentCreatedFromReport}
			/>
		</>
	);
};

export default CreateReportForm;

list_page.ServiceReports.js:
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { getAllReports, getReportByTicketId } from "../../Services/reportsService";
import { getQuoteById } from "../../Services/quoteService";
import CustomDatagrid from "../CustomDatagrid/CustomDatagrid";
import { Alert, Box, Button, Drawer, FormControlLabel, Switch, Tab, Tabs, Tooltip, Typography, useMediaQuery, TextField, InputAdornment } from "@mui/material";
import LoadingWrapper from "../LoadingWrapper/LoadingWrapper";
import ErrorAlertWrapper from "../ErrorAlertWrapper/ErrorAlertWrapper";
import ServiceReportTimeLog from "../ServiceReportsTimeLog/ServiceReportsTimeLog";
import UserName from "../UserName/UserName";
import { useCustomTheme } from "../../Context/ThemeContext";
import { formatDate } from "../../Services/globalServiceUtils";
import ReceiptIcon from "@mui/icons-material/Receipt";
import SearchIcon from "@mui/icons-material/Search";
import { FaSortAmountDownAlt, FaSortAmountUpAlt } from "react-icons/fa";
import Swal from "sweetalert2";
import { useAuth } from "../../Context/AuthContext";
import ServiceReportReview from "../ServiceReportReview/ServiceReportReview";
import { changeTicketStatus } from "../../Services/ticketsService";
import { toast } from "../../Utilities/toast";
import { useNamespace } from "../../Context/NamespaceContext";
import ServiceReportAppointmentGroup from "../ServiceReportAppointmentGroup/ServiceReportAppointmentGroup";

const ServiceReports = ({
	ticket_id = null,
	ticket,
	activeReports,
	setActiveReports,
	serviceReports,
	setServiceReports,
	Datagridkey,
}) => {
	const { flexRow, flexCol } = useCustomTheme();

	const [quotes, setQuotes] = useState([]);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState(null);
	const [selectedReports, setSelectedReports] = useState([]);
	const [tabIndex, setTabIndex] = useState(0);
	const [isServiceManager, setIsServiceManager] = useState(false);
	const [selectedReportWorkLog, setSelectedReportWorkLog] = useState(null);
	const [viewReportFormOpen, setViewReportFormOpen] = useState(null);
	const [groupByAppointmentView, setGroupByAppointmentView] = useState(false);
	const [groupedSearchText, setGroupedSearchText] = useState("");
	const [sortOrder, setSortOrder] = useState("desc"); // "desc" = newest first
	const { user, userMode } = useAuth();
	const { getNamespace } = useNamespace();
	const isLargeScreen = useMediaQuery("(min-width:1500px)");
	const isSmallScreen = useMediaQuery("(max-width:600px)");
	const formDrawerWidth = isLargeScreen ? "50vw" : "65vw";
	const onSortChange = useCallback((newOrder) => setSortOrder(newOrder), []);

	const appointmentGroupingToggle = (
		<FormControlLabel
			sx={{ ml: 0 }}
			control={
				<Switch
					size="small"
					checked={groupByAppointmentView}
					onChange={(e) => setGroupByAppointmentView(e.target.checked)}
				/>
			}
			label={
				<Typography variant="body2" sx={{ userSelect: "none" }}>
					Group by {getNamespace("appointment", { capitalize: true, plural: false })}
				</Typography>
			}
		/>
	);

	const appointmentSortButton = groupByAppointmentView ? (
		<Tooltip title={`Sort by date ${sortOrder === "asc" ? "descending" : "ascending"}`}>
			<Button variant="roundedGreyBgSquareContained" onClick={() => onSortChange(sortOrder === "asc" ? "desc" : "asc")}>
				{sortOrder === "asc" ? <FaSortAmountUpAlt /> : <FaSortAmountDownAlt />}
			</Button>
		</Tooltip>
	) : null;

	const reportGroupsByAppointment = useMemo(() => {
		if (!groupByAppointmentView) return [];

		const list = Array.isArray(serviceReports) ? serviceReports : [];
		const q = (groupedSearchText || "").trim().toLowerCase();
		const groups = new Map();

		list.forEach((row) => {
			const apptId = row?.appointment_id;
			const key = apptId ? String(apptId) : "__no_appt__";
			const label =
				row?.appointment_title ||
				(apptId
					? `${getNamespace("appointment", { capitalize: true, plural: false })} #${apptId}`
					: `No ${getNamespace("appointment", { capitalize: true, plural: false })}`);

			if (!groups.has(key)) {
				groups.set(key, {
					key,
					label,
					rows: [],
					start: row?.appointment_start_datetime || row?.appointment_startDate || row?.appointment_start || null,
					end: row?.appointment_end_datetime || row?.appointment_endDate || row?.appointment_end || null,
				});
			}
			const entry = groups.get(key);
			// Keep first known start/end; fall back to later rows if missing
			if (!entry.start) {
				entry.start = row?.appointment_start_datetime || row?.appointment_startDate || row?.appointment_start || null;
			}
			if (!entry.end) {
				entry.end = row?.appointment_end_datetime || row?.appointment_endDate || row?.appointment_end || null;
			}
			entry.rows.push(row);
		});

		const out = Array.from(groups.values());
		out.sort((a, b) => {
			if (a.key === "__no_appt__" && b.key !== "__no_appt__") return 1;
			if (a.key !== "__no_appt__" && b.key === "__no_appt__") return -1;

			const getGroupTime = (g) => {
				const rows = Array.isArray(g?.rows) ? g.rows : [];
				let minCreated = NaN;
				let maxCreated = NaN;
				rows.forEach((r) => {
					const t = (r?.created && new Date(r.created).getTime()) || NaN;
					if (!Number.isFinite(t)) return;
					if (!Number.isFinite(minCreated) || t < minCreated) minCreated = t;
					if (!Number.isFinite(maxCreated) || t > maxCreated) maxCreated = t;
				});
				if (sortOrder === "asc") return minCreated;
				return maxCreated;
			};

			const aTime = getGroupTime(a);
			const bTime = getGroupTime(b);
			const aHas = Number.isFinite(aTime);
			const bHas = Number.isFinite(bTime);

			if (aHas && bHas && aTime !== bTime) {
				return sortOrder === "asc" ? aTime - bTime : bTime - aTime;
			}
			if (aHas && !bHas) return -1;
			if (!aHas && bHas) return 1;
			return String(a.label || "").localeCompare(String(b.label || ""));
		});
		if (!q) return out;

		return out
			.map((g) => {
				const groupLabelText = String(g?.label || "");
				const appointmentMatches = groupLabelText.toLowerCase().includes(q);
				if (appointmentMatches) return g;

				const matchingRows = (Array.isArray(g?.rows) ? g.rows : []).filter((row) => {
					const reportName = String(row?.report_number || row?.report_name || row?.report_title || "");
					return reportName.toLowerCase().includes(q);
				});

				if (matchingRows.length === 0) return null;
				return { ...g, rows: matchingRows };
			})
			.filter(Boolean);
	}, [groupByAppointmentView, serviceReports, getNamespace, groupedSearchText, sortOrder]);

	useEffect(() => {
		if (user) {
			console.log("Logged In: ", user);
			if (userMode === "agent") {
				const userRole = user.account.isservicemanager;
				setIsServiceManager(userRole);
				setTabIndex(0);
			} else if (userMode === "user") {
				setTabIndex(0);
			}
		}
	}, [user]);

	const handleTabChange = (event, newValue) => {
		setTabIndex(newValue);
	};

	// useEffect(() => {
	// 	fetchServiceReports();
	// }, []);

	const columns = [
		{
			field: "report_number",
			headerName: `${getNamespace("service_report", {
				capitalize: true,
				plural: false,
			})} Number`,
			width: 160,
			align: "left",
			headerAlign: "left",
			renderCell: (params) => (
				<Tooltip
					title={`View ${getNamespace("service_report", {
						capitalize: true,
						plural: false,
					})} Details`}>
					<span
						style={{
							cursor: "pointer",
						}}>
						{params.value}
					</span>
					{userMode === "user" && params.row.report_status === "submitted" && (
						<span style={{ color: "#aaa", fontSize: "11px", marginLeft: "10px" }}>
							- Awaiting your Approval
						</span>
					)}
				</Tooltip>
			),
		},
		{
			field: "quote_number",
			headerName: `${getNamespace("quote", {
				capitalize: true,
				plural: false,
			})} Number`,
			flex: 1.6,
			minWidth: 220,
			align: "left",
			headerAlign: "left",
			renderCell: (params) =>
				!params.value ? <span style={{ fontSize: "10px", color: "gray" }}>N/A</span> : params.value,
		},
		{
			field: "appointment_title",
			headerName: getNamespace("appointment", {
				capitalize: true,
				plural: false,
			}),
			flex: 1.2,
			minWidth: 180,
			align: "left",
			headerAlign: "left",
			renderCell: (params) =>
				!params.value ? <span style={{ fontSize: "10px", color: "gray" }}>N/A</span> : params.value,
		},
		{
			field: "report_creator",
			headerName: "Created By",
			width: 120,
			align: "left",
			headerAlign: "left",
			renderCell: (params) =>
				!params.value ? (
					<span style={{ fontSize: "10px", color: "gray" }}>N/A</span>
				) : (
					<Box
						sx={{
							...flexCol,
							justifyContent: "center",
							alignItems: "flex-start",
							width: "100%",
							height: "100%",
						}}>
						<UserName name={params.value} />
					</Box>
				),
		},
		{
			field: "report_status",
			headerName: "Status",
			width: userMode === "user" && isSmallScreen ? 170 : 120,
			align: "center",
			headerAlign: "center",
			renderCell: (params) => {
				let statusText = "";
				if (!params.value || params.value === "") {
					statusText = `<span style="font-size: 11px; color: #aaa;">Unknown</span>`;
				} else {
					const capitalizedValue = params.value.charAt(0).toUpperCase() + params.value.slice(1);
					statusText = `<b>${capitalizedValue}</b>`;
				}
				return <span dangerouslySetInnerHTML={{ __html: statusText }} />;
			},
		},
		{
			field: "created",
			headerName: "Created Date",
			width: 180,
			align: "left",
			headerAlign: "left",
			renderCell: (params) => formatDate(params.value),
		},
	];

	const customButtons = [
		{
			label: "Generate Invoice",
			icon: <ReceiptIcon />,
			onClick: () => {
				handleGenerateInvoice();
			},
		},
	];

	const handleGenerateInvoice = async () => {
		if (selectedReports.length <= 0) {
			Swal.fire({
				icon: "info",
				title: "Info",
				text: `Please select a ${getNamespace("service_report", {
					capitalize: true,
					plural: false,
				})} to generate Invoice`,
				confirmButtonText: "Okay",
			});
			return;
		}

		const selectedReport = serviceReports.find((report) => report.id === selectedReports[0]);
		if (selectedReport.report_status !== "approved") {
			Swal.fire({
				icon: "warning",
				title: "Warning",
				html: `<span>${getNamespace("service_report", {
					capitalize: true,
					plural: false,
				})} needs to be <b>Approved By Customer</b> before generating Invoice</span>`,
				confirmButtonText: "Okay",
			});
			return;
		}

		Swal.fire({
			icon: "success",
			title: "Success",
			html: "<span>Invoice Generated and Sent to Customer</span>",
			confirmButtonText: "Okay",
		});

		const result = await Swal.fire({
			icon: "success",
			title: "Success",
			html: `<span>Invoice Generated and Sent to Customer</span> <br> <span>Do you want to close the ${getNamespace(
				"ticket",
				{
					capitalize: true,
					plural: false,
				}
			)} now?</span>`,
			showCancelButton: true,
			confirmButtonText: "Yes, close it",
			cancelButtonText: "No",
		});

		if (result.isConfirmed) {
			const response = await changeTicketStatus({ ticket_id: ticket.ticket_id, status_id: 3 });
			if (response.status) {
				console.log("Generating Report Invoice: ", selectedReports);
				toast.fire({
					message: `${getNamespace("ticket", {
						capitalize: true,
						plural: false,
					})} Closed`,
					severity: "success",
					duration: 2000,
				});
			}
		}
	};

	const fetchServiceReports = async () => {
		setLoading(true);
		try {
			const response = ticket_id ? await getReportByTicketId(ticket_id) : await getAllReports();
			console.log(response);
			if (response.status) {
				const allReports = response.data.map((report) => ({
					id: report.report_id,
					report_number: report.report_number,
					quote_number: report?.quote?.quote_number || null,
					appointment_id: report?.appointment_id || null,
					appointment_title: report?.appointment?.title || null,
					appointment_start_datetime: report?.appointment?.start_datetime || report?.appointment?.startDate || null,
					appointment_end_datetime: report?.appointment?.end_datetime || report?.appointment?.endDate || null,
					report_creator: report?.service_engineer?.name || "",
					created: report.createdAt,
					report_status: report?.report_status,
				}));
				setServiceReports(allReports);

				// Process each report individually
				const groupedReports = await Promise.all(
					response.data.map(async (report) => {
						const quoteResp = await fetchQuoteItems(report.quote_id);
						const combinedData = combineQuotedAndWorkLogs(
							quoteResp?.data?.quote_line_items || [],
							report.work_logs
						);

						return {
							report_id: report.report_id,
							report_number: report.report_number,
							report_quote_id: report.quote_id,
							logs: groupByItemType(combinedData),
						};
					})
				);
				console.log("Grouped Items: ", groupedReports);
				setActiveReports(groupedReports);
				setLoading(false);
			}
		} catch (error) {
			console.log(error);
			setLoading(false);
			setError("Failed fetching Service Reports");
		}
	};

	const fetchQuoteItems = async (quote_id) => {
		console.log(quote_id);
		if (quote_id) {
			const response = await getQuoteById(quote_id);
			console.log(response);
			return response;
		}
		return [];
	};

	const combineQuotedAndWorkLogs = (quotedItems, workLogs) => {
		const resultMap = new Map();

		// Add quoted items to map
		quotedItems.forEach((q) => {
			const id = q.item_id;
			if (!resultMap.has(id)) {
				resultMap.set(id, {
					item_id: id,
					item_name: q.quoted_item?.name || "Unknown",
					item_type: q.quoted_item?.item_type?.name || "",
					estimated: 0,
					actual: 0,
					unit: q.item_unit || "",
					loggers: [],
				});
			}
			resultMap.get(id).estimated += q.item_value;
		});

		// Add work logs and build logger summaries
		workLogs.forEach((w) => {
			const id = w.item_id;
			if (!resultMap.has(id)) {
				resultMap.set(id, {
					item_id: id,
					item_name: w.work_item?.name || "Unknown",
					item_type: w.work_item?.item_type?.name || "",
					estimated: 0,
					actual: 0,
					unit: w.item_unit || "",
					loggers: [],
				});
			}

			const entry = resultMap.get(id);
			entry.actual += w.item_value;

			const loggerName = w.staff?.name || "Unknown";
			const unit = w.item_unit || "";

			// Find existing logger entry
			let loggerEntry = entry.loggers.find((l) => l.loggerName === loggerName);

			if (loggerEntry) {
				loggerEntry.actual += w.item_value;
			} else {
				entry.loggers.push({
					loggerName,
					actual: w.item_value,
					unit,
				});
			}
		});

		// Convert to array and compute balance
		return Array.from(resultMap.values()).map((item) => ({
			...item,
			balance: item.estimated - item.actual,
		}));
	};

	// New function to group by item_type
	const groupByItemType = (combinedData) => {
		const grouped = combinedData.reduce((acc, item) => {
			const itemType = item.item_type || "Unknown";

			if (!acc[itemType]) {
				acc[itemType] = [];
			}

			acc[itemType].push({
				item_id: item.item_id,
				item_name: item.item_name,
				estimated: item.estimated,
				actual: item.actual,
				balance: item.balance,
				unit: item.unit,
				loggers: item.loggers || [], // include loggers
			});

			return acc;
		}, {});

		// Convert to array format
		return Object.entries(grouped).map(([itemType, items]) => ({
			item_type_name: itemType,
			items: items,
		}));
	};

	const handleRowSelect = (selectedRows) => {
		const idArray = Array.from(selectedRows.ids);

		console.log("Selected row IDs:", idArray);
		setSelectedReports(idArray);
	};

	const handleRowClick = (params) => {
		console.log("Row clicked:", params.row);
		// navigate(`/customers/${params.row.id}`);
		setSelectedReportWorkLog(params.row.id);
		setViewReportFormOpen(true);
	};

	if (loading) {
		return <LoadingWrapper minHeight={"300px"} />;
	}

	if (error && !loading) {
		return <ErrorAlertWrapper minHeight={"300px"} error={error} />;
	}
	return (
		<>
			<Box sx={{ width: "100%", px: 2 }}>
				<Box
					sx={{
						borderBottom: 1,
						borderColor: "divider",
						mb: 2,
						backgroundColor: "background.paper",
					}}>
					<Tabs value={tabIndex} onChange={handleTabChange}>
						{userMode === "agent" && (
							<Tab
								label={`Active ${getNamespace("service_report", {
									capitalize: true,
									plural: false,
								})}`}
							/>
						)}
						<Tab
							label={`All ${getNamespace("service_report", {
								capitalize: true,
								plural: true,
							})}`}
						/>
					</Tabs>
				</Box>
				{userMode === "agent" && tabIndex === 0 && (
					<Box>
						{activeReports && activeReports.length > 0 ? (
							<ServiceReportTimeLog
								reports={activeReports}
								setReports={setActiveReports}
								fetchReports={fetchServiceReports}
								ticket_id={ticket.ticket_id}
								ticket={ticket}
							/>
						) : (
							<Alert severity="info" sx={{ width: "100%", mt: 1 }}>
								No Active{" "}
								{getNamespace("service_report", {
									capitalize: true,
									plural: true,
								})}{" "}
								for this{" "}
								{getNamespace("ticket", {
									capitalize: true,
									plural: false,
								})}
							</Alert>
						)}
					</Box>
				)}
				{((userMode === "agent" && tabIndex === 1) || (userMode === "user" && tabIndex === 0)) && (
					<Box>
						{serviceReports.length > 0 ? (
							groupByAppointmentView ? (
								<Box sx={{ width: "100%" }}>
									<Box
										sx={{
											display: "flex",
											justifyContent: "space-between",
											alignItems: "center",
											gap: 1,
											flexWrap: "wrap",
											mb: 1,
										}}>
										<TextField
											variant="outlined"
											size="small"
											value={groupedSearchText}
											onChange={(e) => setGroupedSearchText(e.target.value)}
											placeholder="Search..."
											data-tour-id="service-report-grouped-search-bar"
											style={{ minWidth: "250px" }}
											InputProps={{
												startAdornment: (
													<InputAdornment position="start">
														<SearchIcon />
													</InputAdornment>
												),
												sx: {
													borderRadius: "10px",
													bgcolor: (theme) => theme.palette.background.paper,
													border: "0px",
												},
											}}
										/>
										<Box sx={{ display: "flex", justifyContent: "flex-end", alignItems: "center", gap: 1, flexWrap: "wrap" }}>
											{appointmentGroupingToggle}
											{appointmentSortButton}
											{isServiceManager && Array.isArray(customButtons) && customButtons.length > 0
												? customButtons.map((btn) => (
														<Button
															key={btn.label}
															size="small"
															variant="contained"
															startIcon={btn.icon}
															onClick={btn.onClick}>
															{btn.label}
														</Button>
												  ))
												: null}
										</Box>
									</Box>
									{reportGroupsByAppointment.length > 0 ? (
										reportGroupsByAppointment.map((g) => (
											<ServiceReportAppointmentGroup
												key={`${Datagridkey}-appt-${g.key}`}
												groupKey={g.key}
												groupLabel={g.label}
												groupRows={g.rows}
												groupStart={g.start}
												groupEnd={g.end}
												datagridKeyPrefix={Datagridkey}
												columns={columns}
												onSelect={handleRowSelect}
												onRowClick={handleRowClick}
												rowIdField={"id"}
												showActions={isServiceManager ? true : false}
												sortBy={[{ field: "created", sort: "desc" }]}
												noDataText={`No ${getNamespace("service_report", { capitalize: true, plural: true })}`}
												getNamespace={getNamespace}
											/>
										))
									) : (
										<Alert severity="info" sx={{ width: "100%", mt: 1 }}>
											No matching {getNamespace("service_report", { capitalize: false, plural: true })} found
										</Alert>
									)}
								</Box>
							) : (
							<CustomDatagrid
								key={Datagridkey}
								data={serviceReports}
								columns={columns}
								rowIdField={"id"}
								onSelect={handleRowSelect}
								rowClick={true}
								onRowClick={handleRowClick}
								checkboxSelection={false}
								disableMultipleRowSelection={true}
								customButtons={isServiceManager ? customButtons : null}
								toolbarRight={appointmentGroupingToggle}
								pageSize={10}
								pageSizeOptions={[5, 10, 25, 50]}
								showMore={false}
								showEdit={false}
								showDuplicate={false}
								showActions={isServiceManager ? true : false}
								sortBy={[{ field: "created", sort: "desc" }]}
							/>
						)
						) : (
							<Alert severity="info" sx={{ width: "100%", mt: 1 }}>
								No{" "}
								{getNamespace("service_report", {
									capitalize: true,
									plural: true,
								})}{" "}
								found for this{" "}
								{getNamespace("ticket", {
									capitalize: true,
									plural: false,
								})}
							</Alert>
						)}
					</Box>
				)}
			</Box>
			{viewReportFormOpen && selectedReportWorkLog && (
				<Drawer anchor={"right"} sx={{ width: "65vw" }} open={viewReportFormOpen}>
					<ServiceReportReview
						ticket={ticket}
						open={viewReportFormOpen}
						setOpen={setViewReportFormOpen}
						fetchParentData={fetchServiceReports}
						selectedReportId={selectedReportWorkLog}
						setSelectedReportId={setSelectedReportWorkLog}
					/>
				</Drawer>
			)}
		</>
	);
};

export default ServiceReports;

