const getServiceReportFormOptions = async (req, res) => {
	const { ticket_id, report_flow } = req.body || {};
	if (!ticket_id) {
		return res.status(400).json({ status: false, message: "ticket_id is required" });
	}

	try {
		const ticketData = await models.ticket.findOne({ where: { ticket_id } });
		if (!ticketData) {
			throw new AppError("NOT_FOUND", { entity: `${capitalizeFirstLetter(getTicketNamingConvention())}` });
		}

		// Access check (match createReport behavior)
		if (req.user?.staff_id) {
			const deptAccess = await models.staff_dept_access.findAll({
				where: { staff_id: req.user.staff_id },
				attributes: ["dept_id"],
				raw: true,
			});
			const userDeptIds = deptAccess.map((d) => d.dept_id);

			const collabTickets = await models.ticket_collaborators.findAll({
				where: { staff_id: req.user.staff_id },
				attributes: ["ticket_id"],
				raw: true,
			});
			const collabTicketIds = collabTickets.map((c) => c.ticket_id);

			const hasAccess =
				ticketData.assigned_staff_id === req.user.staff_id ||
				ticketData.accountable_staff_id === req.user.staff_id ||
				ticketData.created_by_staff_id === req.user.staff_id ||
				collabTicketIds.includes(ticketData.ticket_id) ||
				userDeptIds.includes(ticketData.dept_id);

			if (!hasAccess) {
				throw new AppError("FORBIDDEN", {
					entity: `${capitalizeFirstLetter(getServiceReportNamingConvention())}`,
					details: "You do not have permission to access this ticket",
				});
			}
		}

		const serviceTypeId = ticketData?.service_type ? Number(ticketData.service_type) : null;
		if (!serviceTypeId) {
			return res.status(200).json({ status: true, data: { forms: [], default_form_id: null } });
		}

		const eligible = await getEligibleServiceReportFormsForServiceType({
			service_type_id: serviceTypeId,
			report_flow: normalizeReportFlow(report_flow),
			transaction: null,
		});

		return res.status(200).json({
			status: true,
			data: {
				forms: eligible.forms || [],
				default_form_id: eligible.default_form_id || null,
			},
		});
	} catch (error) {
		const status = error.statusCode || 500;
		return res.status(status).json({
			status: false,
			message: error.statusCode ? error.message : "Failed to fetch report form options",
			error: process.env.NODE_ENV === "development" ? error.message : undefined,
		});
	}
};

